<script setup lang="ts">
import { useApi } from '../../api/client'
import { apiError } from '../../utils/apiError'
import { formatChangeReport, relativeTime, backfillPercent } from '../../utils/site'
const api = useApi(); const toast = useToast(); const page = ref(1); const size = 20
const { data, error, refresh, status } = await useAsyncData('sites', async () => { const r = await api.GET('/sites', { params: { query: { offset: (page.value - 1) * size, limit: size } } }); if (!r.data) throw new Error(apiError(r.error)); return r.data }, { watch: [page] })
async function toggle(id: string, enabled: boolean) { const r = await api.PATCH('/sites/{site_id}', { params: { path: { site_id: id } }, body: { enabled } }); if (!r.data) toast.add({ title: 'Could not update site', description: apiError(r.error), color: 'error' }); await refresh() }
async function check(id: string) { const r = await api.POST('/sites/{site_id}/check', { params: { path: { site_id: id } } }); if (!r.data) toast.add({ title: r.response.status === 409 ? 'A check is already running' : 'Could not start check', color: 'error' }); else { toast.add({ title: 'Check started' }); await refresh() } }
</script>
<template><div><PageHeader title="Sites" description="Manage sites and their check schedules."><template #actions><UButton to="/sites/new">Add site</UButton></template></PageHeader>
<UAlert v-if="error" color="error" :description="error.message" />
<p v-else-if="status === 'pending' || !data">Loading sites…</p>
<div v-else-if="!data.items.length" class="rounded-xl border border-dashed p-6 text-muted">No sites yet. <UButton to="/sites/new" variant="link">Add site</UButton></div>
<div v-else class="overflow-x-auto rounded-xl border border-default"><table class="w-full text-left text-sm"><thead><tr><th scope="col" v-for="h in ['Name', 'Domain', 'Language', 'Enabled', 'Every', 'Daily cap', 'Backfill', 'Last check', 'Next check', '']" :key="h" class="p-3">{{ h }}</th></tr></thead><tbody class="divide-y divide-default"><tr v-for="s in data?.items" :key="s.id"><td class="p-3"><NuxtLink class="text-primary hover:underline" :to="`/sites/${s.id}`">{{ s.name }}</NuxtLink></td><td class="p-3">{{ s.domain }}</td><td class="p-3">{{ s.language }}</td><td class="p-3"><input type="checkbox" :checked="s.enabled" :aria-label="`Enable ${s.name}`" @change="toggle(s.id, ($event.target as HTMLInputElement).checked)"></td><td class="p-3 whitespace-nowrap">{{ s.check_every_minutes % 60 === 0 ? `${s.check_every_minutes / 60} h` : `${s.check_every_minutes} min` }}</td><td class="p-3">{{ s.daily_cap }}</td><td class="p-3"><UBadge color="neutral">{{ s.backfill_state }}</UBadge> {{ backfillPercent(s.backfill_progress?.done ?? 0, s.backfill_progress?.found ?? 0) }}%</td><td class="p-3"><template v-if="s.last_crawl">{{ formatChangeReport(s.last_crawl.counters) }}<br><span class="text-muted">{{ relativeTime(s.last_crawl.created_at) }}</span> <StatusBadge :status="s.last_crawl.status" /></template><span v-else>Never</span></td><td class="p-3">{{ s.enabled ? relativeTime(s.next_check_at) : 'Disabled' }}</td><td class="p-3"><UButton size="sm" @click="check(s.id)">Check now</UButton></td></tr></tbody></table></div><UPagination v-if="data && data.total > size" v-model:page="page" :items-per-page="size" :total="data.total" /></div></template>
